/* QuickSight 4c19425b-e091-4571-9563-3befd7d26432 
 {"partner":"QuickSight","entityId":"1e27d052-93e4-42ae-9847-cb688b7f08c5","sheetId":"1e27d052-93e4-42ae-9847-cb688b7f08c5_f7c32031-6a46-4147-8457-ae6e92950f16","visualId":"1e27d052-93e4-42ae-9847-cb688b7f08c5_414d922d-4190-4839-89bd-cbc96d2d49f6"} */
